"""Demand-first results, inspectable case finder, and bounded evidence."""
import base64,collections,hashlib,html,json
from pathlib import Path
import numpy as np
from data import ROOT
from catalog import MISSIONS,queries,catalog
def quantiles(values):return dict(zip(['p50','p95','p99','max'],map(float,np.quantile(values,[.5,.95,.99,1])))) if values else {}
def main():
 p=ROOT/'results/canonical';meta=json.loads((p/'meta.json').read_text());seen=set();workflows=set();sql_hashes=set();counts=collections.Counter();by_req=collections.defaultdict(collections.Counter);by_client=collections.defaultdict(collections.Counter);lat=[];sql_lat=[];analysis_lat=[];stage_count=0;source_rows=0;decisions=0;business_checks=0;publication_steps=0;commits=0;rollbacks=0;finder=[];examples={};failures=[]
 for name,digest in json.loads((ROOT/'canonical-code-manifest.json').read_text()).items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest,('execution code changed',name)
 with (ROOT/'cases.jsonl').open('w') as master,(ROOT/'failures.jsonl').open('w') as bad:
  for file in sorted(p.glob('cases-*.jsonl')):
   for line in file.open():
    r=json.loads(line);case=r['case_id'];assert case not in seen;seen.add(case);f,i=divmod(case,250);assert r['requirement']==MISSIONS[f]['key'];assert [s['sql'] for s in r['stages']]==queries(f,i) if r['status']=='pass' else True
    counts[r['status']]+=1;by_req[r['requirement']][r['status']]+=1;by_client[r['client']][r['status']]+=1;lat.append(r['total_ms']);master.write(line)
    signature={'requirement':r['requirement'],'parameter':i,'parameters':r['parameters'],'sql':queries(f,i)};workflows.add(hashlib.sha256(json.dumps(signature,sort_keys=True).encode()).hexdigest())
    for stage in r['stages']:sql_hashes.add(hashlib.sha256(stage['sql'].encode()).hexdigest());sql_lat.append(stage['query_ms']);source_rows+=stage['actual']['rows'];stage_count+=1
    model=r.get('actual_analysis',{});decisions+=len(model.get('decisions',[]));business_checks+=len(model.get('checks',{}));publication_steps+=len(r.get('publication',[]));commits+=any(s['sql']=='COMMIT' for s in r.get('publication',[]));rollbacks+=any(s['sql']=='ROLLBACK' for s in r.get('publication',[]))
    if 'analysis_ms' in r:analysis_lat.append(r['analysis_ms'])
    entry={'case_id':case,'requirement':r['requirement'],'question':r['question'],'status':r['status'],'parameters':r['parameters'],'metrics':model.get('metrics',{}),'checks':model.get('checks',{}),'decisions_top5':model.get('decisions',[])[:5],'error':r.get('error')};finder.append(entry);examples.setdefault(r['requirement'],entry)
    if r['status']!='pass':bad.write(line);failures.append(entry)
 assert seen==set(range(10000));assert len(workflows)==10000
 assert all(sum(v.values())==250 for v in by_req.values())
 health=[json.loads(l) for file in p.glob('health*.jsonl') for l in file.open()];supp={}
 for name in ['spark','flink']:
  directory=ROOT/'results'/name
  if (directory/'meta.json').exists():supp[name]={'meta':json.loads((directory/'meta.json').read_text()),'cases':[json.loads(l) for l in (directory/'cases.jsonl').open()]}
 result={'canonical':meta,'verified_unique_cases':len(seen),'unique_workflow_signatures':len(workflows),'distinct_extract_sql_hashes':len(sql_hashes),'counts':dict(counts),'by_requirement':dict(by_req),'by_client':dict(by_client),'verified_extract_datasets':stage_count,'extracted_rows_compared':source_rows,'decision_rows_compared':decisions,'business_constraint_checks':business_checks,'publication_steps':publication_steps,'published_cases':commits,'cancelled_cases':rollbacks,'latency_ms':{'complete_case':quantiles(lat),'extract_query':quantiles(sql_lat),'paired_reference_and_actual_analysis':quantiles(analysis_lat)},'health':{'samples':len(health),'errors':[r for r in health if r['status']!='ok'],'pids':sorted({r['pid'] for r in health}),'peak_rss_mib':max(r.get('rss_mib',0) for r in health)},'requirements':catalog(),'supplemental_engines':supp,'source_integrity':json.loads((ROOT/'data-integrity-final.json').read_text()),'scope':{'case_definition':'40 independent business questions ×250 distinct time/entity/budget/risk configurations; a case includes facts, scientific analysis, business constraints and publication audit. Extracts/rows/assertions do not inflate case count.','reference':'DuckDB built from original synthetic tables. Every full fact dataset compared; independent Pandas accounting/day-grid check and complete source validation. Scientific model applied separately to reference facts and MO facts. Constraints checked independently of equality.','numerics':'Integral fields exact; continuous extracted facts rtol/atol 1e-7. Decision model inputs normalized to eight decimals after full comparison, defining deterministic ties.','payload':'All SQL, parameters, full final expected/actual analyses retained. Successful fact extraction stores shape, full-array hash and first/last row samples; complete failing extracts retained. Original input files and code reproduce every fact matrix.','calendar_correction':'Sparse observed-day averages were corrected to dense calendar-day facts. 3000 identical previously passed workflows were retained only after source/analytical-code hashes and exact SQL/parameters matched; affected workflows reexecuted. Original partial attempts remain separate. Final 10000 IDs each occur once.','timing':'Canonical times are observed under mixed local reference/scientific/JVM load. Isolated full-analysis benchmark, if present, is separate.','model_limits':'Synthetic business assumptions. Normal forecast intervals and observational marketing/price estimates are approximate; compatibility and constraint validity do not establish production predictive quality or causal effects.','stability':'Local four CPU quota,16GiB instance; monitored execution window only.'}}
 for name in ['environment','final-state','performance','client-notes','failure-analysis']:
  if (ROOT/(name+'.json')).exists():result[name]=json.loads((ROOT/(name+'.json')).read_text())
 (ROOT/'report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));(ROOT/'case-index.json').write_text(json.dumps(sorted(finder,key=lambda r:r['case_id']),ensure_ascii=False))
 esc=lambda x:html.escape(str(x))
 def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+esc(k)+'</th>' for k in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
 sections=['<p>从分析需求定义输入、产物与验收条件。每个案例包含业务事实提取、统计或优化计算、结果与决策核对、业务约束检查，以及结果回写和发布审计。40 类问题，各 250 组配置，独立统计 10,000 个完整案例。</p>',table(['完整案例','通过','SQL错误','事实差异','分析差异','回写错误','基准框架错误'],[[len(seen),counts['pass'],counts['sql_error'],counts['extract_mismatch'],counts['analysis_mismatch'],counts['publication_error'],counts['harness_error']]]),f'<p>共核对 {stage_count:,} 个事实数据集、{source_rows:,} 行事实、{decisions:,} 行决策和 {business_checks:,} 项业务约束；回写流程共 {publication_steps:,} 步。发布 {commits:,} 例，取消发布 {rollbacks:,} 例，全部结果工作表已清空。</p>']
 sections+=['<h2>按业务需求查看案例</h2>','<label>分析需求 <select id="mission">'+''.join(f'<option value="{f}">{esc(m["question"])}</option>' for f,m in enumerate(MISSIONS))+'</select></label> <label>案例 ID <input id="case" type="number" value="0" min="0" max="9999"></label><pre id="case-detail"></pre>']
 sections+=['<h2>40 类需求与判定标准</h2>',table(['分析需求','验收条件','通过／总数'],[[m['question'],m['acceptance'],f'{by_req[m["key"]]["pass"]}/250'] for m in MISSIONS])]
 sections+=['<h2>性能与稳定性</h2>',table(['观测计时','P50毫秒','P95毫秒','P99毫秒','最大毫秒'],[[name,*[round(v[k],2) for k in ['p50','p95','p99','max']]] for name,v in result['latency_ms'].items()]),f'<p>数据库心跳 {len(health)} 次，错误 {len(result["health"]["errors"])} 次；PID {esc(result["health"]["pids"])}，峰值 RSS {result["health"]["peak_rss_mib"]:.1f} MiB。观测包含本地基准、科学计算及引擎客户端竞争。</p>']
 if 'performance' in result:
  sections+=['<h3>独立分析工作流测量</h3><p>计时包含 MO 读取及 Pandas/NumPy/SciPy 计算，不含结果发布写入；基准预先计算，核对在计时后进行。</p>',table(['并发','工作流数','工作流/秒','P50毫秒','P95毫秒','P99毫秒','核对结果'],[[g['concurrency'],g['workflows'],round(g['workflows_per_second'],2),*[round(g['latency_ms'][k],2) for k in ['p50','p95','p99']],g['counts']] for g in result['performance']['groups']])]
  if (ROOT/'performance.png').exists():sections.append('<img style="width:100%" alt="Business workflow throughput and latency" src="data:image/png;base64,'+base64.b64encode((ROOT/'performance.png').read_bytes()).decode()+'">')
 sections+=['<h2>Spark / Flink 需求分析补测</h2>',table(['引擎','完整需求工作流','通过','错误'],[[name,e['meta']['workflows'],e['meta']['counts'].get('pass',0),e['meta']['counts'].get('pipeline_error',0)] for name,e in supp.items()]),'<p>各八个额外工作流：利润归因、多触点归因、需求预测、现金流、资产配置、能源、维护、经营规划。业务事实 SQL 在引擎中执行，经 JDBC 读写 MO；统计与优化模型在 Python 中计算，最终决策经 MySQL 协议回写。补测不计入主批次 10,000。</p>']
 state=result.get('final-state',{});trace=state.get('internal_trace_failed_loads',0)
 trace_note=f'<p>时间窗内内部 statement_info 追踪 LOAD 失败事件：{trace}。</p>'
 if trace:trace_note+='<p>内部追踪事件与业务查询结果分别统计。此前同类文本超限由 <a href="https://github.com/matrixorigin/matrixone/issues/29809">#29809</a> 跟踪；本批次事件归属与原因见完整日志证据。</p>'
 sections+=['<h2>问题与方法边界</h2>',trace_note,f'<p>现金流日均口径已补齐无订单日期，并用独立 Pandas 核对。保留的 {meta.get("retained_identical_verified_cases",0)} 条旧记录均通过数据、科学代码和 SQL/参数一致性验证；受影响流程已重算，最终每个 ID 只出现一次。原始尝试单独保留。</p>',table(['失败案例','问题'],[[r['case_id'],r['error']] for r in failures]) if failures else '<p>主批次无失败案例。</p>']
 for name in ['scope','environment','final-state','client-notes','failure-analysis']:
  if name in result:sections.append('<details><summary>'+esc(name)+' 证据与方法</summary><pre>'+esc(json.dumps(result[name],ensure_ascii=False,indent=2))+'</pre></details>')
 embedded=json.dumps(sorted(finder,key=lambda r:r['case_id']),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 script='<script>const cases='+embedded+';const box=document.getElementById("case"),mission=document.getElementById("mission");function show(){const id=Math.max(0,Math.min(9999,Number(box.value)||0));box.value=id;mission.value=Math.floor(id/250);document.getElementById("case-detail").textContent=JSON.stringify(cases[id],null,2);}box.addEventListener("input",show);mission.addEventListener("change",()=>{box.value=Number(mission.value)*250;show();});show();</script>'
 style='body{font:15px/1.65 system-ui,sans-serif;max-width:1320px;margin:32px auto;padding:0 24px;color:#172435;background:#f5f8fc}h1{font-size:30px}h2{margin-top:32px}table{border-collapse:collapse;width:100%;background:white;font-size:13px}th,td{border:1px solid #d8e1ef;padding:9px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#dbeafe}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef2f8;padding:18px;font-size:12px;max-height:650px;overflow:auto}select{max-width:85%;padding:8px}input{width:90px;padding:8px}a{color:#165ea6}'
 (ROOT/'report.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MatrixOne 需求驱动分析 10000 例</title><style>'+style+'</style><h1>MatrixOne 需求驱动分析 10,000 例实测</h1>'+''.join(sections)+script+'</html>')
 print(json.dumps({k:result[k] for k in ['counts','verified_unique_cases','verified_extract_datasets','decision_rows_compared','business_constraint_checks','health']},indent=2))
if __name__=='__main__':main()
